class _SkipBlankFormatter(logging.Formatter):
    """Formatter that skips log messages consisting only of blank lines or whitespace."""

    def format(self, record: logging.LogRecord) -> str:
        """Format a log record, returning an empty string to skip blank-line messages.

        Args:
            record: The log record to format.

        Returns:
            str: The formatted log string, or an empty string for blank-line messages.
        """
        # Suppress output to the log file when the message is whitespace-only
        if record.getMessage().strip() in ("", "\n"):
            return ""
        return super().format(record)

def get_config_value(
    key: str, default: object = _REQUIRED, var_type: type = str,
) -> str | int | float | bool | None:
    """Retrieve an environment variable and return it converted to the specified type.

    Args:
        key: Environment variable name.
        default: Default value when the variable is not set.
                 If omitted, raises ValueError when the variable is missing.
        var_type: Target type for conversion (str / int / float / bool).

    Returns:
        The converted configuration value.

    Raises:
        ValueError: If a required environment variable is not set.
    """
    value = os.getenv(key)

    # When the environment variable is not set
    if value is None:
        if default is _REQUIRED:
            raise ValueError(
                f"Environment variable '{key}' is not set. "
                f"Please set it in the .env file or your shell."
            )
        if default is None:
            return None
        value = str(default)

    # Type conversion
    if var_type == bool:
        return value.lower() in ("true", "1", "yes", "on")
    if var_type == int:
        return int(value)
    if var_type == float:
        return float(value)
    return value

